def history_for_existing(apps, schema_editor):
    """Units already in stock start their history with the day they were received."""
    StockSerial = apps.get_model("catalog", "StockSerial")
    SerialEvent = apps.get_model("catalog", "SerialEvent")
    rows = [SerialEvent(serial_id=s.id, event="received", text="Received into stock",
                        stock_point_id=s.stock_point_id, actor_id=s.received_by_id)
            for s in StockSerial.objects.all().only("id", "stock_point_id", "received_by_id")]
    SerialEvent.objects.bulk_create(rows, batch_size=500)
    # keep the real receiving time on those first entries
    for s in StockSerial.objects.all().only("id", "received_at"):
        SerialEvent.objects.filter(serial_id=s.id, event="received").update(at=s.received_at)


